package com.example.lifecycle;

import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;
import org.springframework.beans.factory.BeanNameAware;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

@Component
public class LifecycleDemo implements BeanNameAware {

    @Autowired
    private CacheWarmer warmer; // 第2步才会注入

    public LifecycleDemo() {
        // 第1步：构造器执行时，依赖注入还没发生！
        System.out.println("[1] 构造器: warmer == null ? " + (warmer == null));
    }

    @Override
    public void setBeanName(String name) {
        System.out.println("[3] BeanNameAware: 我是 " + name);
    }

    @PostConstruct
    public void init() {
        // 第5步：依赖已注入完毕，可以放心使用
        System.out.println("[5] @PostConstruct: warmer = " + warmer); 
        warmer.warm();
    }

    @PreDestroy
    public void cleanup() {
        System.out.println("[7] @PreDestroy: 释放资源");
    }
}

class CacheWarmer {
    void warm() {
        System.out.println("[5.1] 预热缓存完成");
    }
}

package com.example.lifecycle;

import jakarta.annotation.PostConstruct;
import org.springframework.beans.factory.InitializingBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

// ══ 三种初始化回调的执行顺序：注解 → 接口 → init-method ══
@Configuration
public class InitOrderDemo {

    // initMethod 指向普通方法，作为第三顺位的初始化回调
    @Bean(initMethod = "customInit")
    public OrderedBean orderedBean() {
        return new OrderedBean();
    }
}

class OrderedBean implements InitializingBean {

    // 顺位 1：@PostConstruct —— 标准注解，最先执行
    @PostConstruct
    public void annotationInit() {
        System.out.println("顺序1: @PostConstruct");
    }

    // 顺位 2：InitializingBean 接口 —— Spring 专有接口回调
    @Override
    public void afterPropertiesSet() {
        System.out.println("顺序2: InitializingBean.afterPropertiesSet");
    }

    // 顺位 3：@Bean(initMethod) 指定的普通方法 —— 与 Spring 解耦，最后执行
    public void customInit() {
        System.out.println("顺序3: init-method 指定的 customInit");
    }
}
